select cls, k, left(md5(cls||chr(1)||k||chr(1)||t),6) h from (
select 'rel' cls, c.relname::text k, concat_ws('|',c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relowner::regrole,c.relpersistence,coalesce(array_to_string(c.reloptions,','),''),(select string_agg(regexp_replace(x::text,'(=[A-Za-z*]*)m([A-Za-z*]*/)','\1\2'),',' order by x::text) from unnest(coalesce(c.relacl,acldefault((case when c.relkind='S' then 's' else 'r' end)::"char",c.relowner))) x where x::text !~ '=m/')) t from pg_class c where c.relnamespace='public'::regnamespace and c.relkind in ('r','p','v','m','S','f')
union all select 'col', c.relname||'.'||a.attname, concat_ws('|',format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attgenerated,a.attidentity,coalesce(pg_get_expr(d.adbin,d.adrelid),'')) from pg_attribute a join pg_class c on c.oid=a.attrelid left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where c.relnamespace='public'::regnamespace and c.relkind in ('r','p','v','m') and a.attnum>0 and not a.attisdropped
union all select 'con', c.relname||'.'||k.conname, k.contype::text||'|'||pg_get_constraintdef(k.oid) from pg_constraint k join pg_class c on c.oid=k.conrelid where c.relnamespace='public'::regnamespace
union all select 'idx', i.indexrelid::regclass::text, regexp_replace(pg_get_indexdef(i.indexrelid),'^CREATE (UNIQUE )?INDEX \S+','') from pg_index i join pg_class c on c.oid=i.indrelid where c.relnamespace='public'::regnamespace
union all select 'pol', schemaname||'.'||tablename||'.'||policyname, concat_ws('|',cmd,permissive,array_to_string(roles,','),coalesce(qual,''),coalesce(with_check,'')) from pg_policies where schemaname in ('public','storage')
union all select 'trg', c.relname||'.'||t.tgname, regexp_replace(pg_get_triggerdef(t.oid),'^CREATE (CONSTRAINT )?TRIGGER \S+','')||'|'||t.tgenabled::text from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and c.relnamespace in ('public'::regnamespace,'storage'::regnamespace)
union all select 'typ', t.typname, t.typtype::text||'|'||coalesce((select string_agg(e.enumlabel,',' order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid),'') from pg_type t where t.typnamespace='public'::regnamespace and t.typtype in ('e','d','c') and (t.typtype<>'c' or exists(select 1 from pg_class c where c.reltype=t.oid and c.relkind='c'))
union all select 'bkt', id, concat_ws('|',public,file_size_limit,coalesce(array_to_string(allowed_mime_types,','),'')) from storage.buckets
union all select 'cron', jobname, concat_ws('|',schedule,active,md5(command)) from cron.job
) x